import pathlib, json, hashlib, datetime
R=pathlib.Path(__file__).parent
P=pathlib.Path('reports/defense-tenth/step4-rebounds-turnover-time')
assert not (R/'protocol.json').exists(), 'Registration already exists'
p={'version':'oreb-full-possession-diagnostic-1','registeredUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'seasons':['2022-23','2023-24','2024-25','2025-26'],'seeds':[20261012,20261013,20261014],'status':'all seasons seen-data; descriptive diagnosis, no engine/card changes or adoption test','base':'pure-oreb-turnover-time-1; retain individual OREB allocation improvement','definitions':{'anchor':'valid individual offensive rebound of missed FG; exclude FT and team rebound anchors','remainingPoints':'own-team FG and ordinary FT points strictly after anchor through end of same possession, including subsequent offensive rebounds','firstAnchor':'first eligible player FG OREB in each possession; one record per possession avoids counting the same scoring outcome twice','allAnchors':'each eligible anchor separately; overlap intentional, never sum as team scoring contribution','specialFT':'exclude whole anchored possession containing technical/flagrant/clearpath/awayfromplay/transitiontake FTs in either source','end':'real: frozen normalizeRealGame possession boundaries; sim: next POSSESSION or PERIOD_END; period end zero-points retained','pointAudit':'real require frozen pointsValid; exclude invalid game and list; sim assert rerun matches and full teams stats equal frozen same-seed output','offenseError':'center(predicted points/game - actual points/game)','defenseError':'center(actual allowed points/game - predicted allowed points/game); positive = defense too strong','identity':'net MSE = offense MSE + defense MSE + 2*covariance; repeat in efficiency proxy space to distinguish pace effect','interval':'20000 franchise + seed bootstrap draws; same franchise sample across four seasons, paired seed sample; equal-season pooled ratio for OREB; 95% only descriptive, no selection','acceptancePolicy':'individual box-score accuracy is an independent objective; retain supported improvements absent significant team harm; no requirement for each change to improve wins'},'bootstrapSeed':20261016,'bootstrapDraws':20000}
inputs=[P/'protocol.json',P/'seed-arrays.json',P/'adapter.mjs',P/'worker.mjs',pathlib.Path('src/defense_pbp_analysis.js')]
p['inputHashes']={str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in inputs}
(R/'protocol.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
h=hashlib.sha256((R/'protocol.json').read_bytes()).hexdigest();(R/'protocol.sha256').write_text(h+'\n',encoding='utf-8');print(h,p['registeredUTC'])
